{"implementation":"def solve(case):
    data = case.get("payload", case) if isinstance(case, dict) else case
    nodes = list(data["nodes"])
    core_distance = data["core_distance"]
    order = {node: index for index, node in enumerate(nodes)}

    edges = []
    for position, edge in enumerate(data["distances"]):
        left, right, distance = edge
        weight = max(distance, core_distance[left], core_distance[right])
        edges.append((weight, order[left], order[right], position, left, right))

    edges.sort(key=lambda item: (item[0], item[1], item[2], item[3]))

    parent = list(range(len(nodes)))
    rank = [0] * len(nodes)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    for weight, left_index, right_index, _, left, right in edges:
        if union(left_index, right_index):
            mst_edges.append([left, right, weight])
            if len(mst_edges) == max(0, len(nodes) - 1):
                break

    return {"mst_edges": mst_edges}
